from collections import Counter
def f(inp):
    H,W=len(inp),len(inp[0])
    bg=Counter(v for row in inp for v in row).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    seed=None; bigcomp=[]
    for r in range(H):
        for c in range(W):
            if inp[r][c]!=bg and not seen[r][c]:
                stack=[(r,c)]; comp=[]
                while stack:
                    a,b=stack.pop(); seen[a][b]=True; comp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            na,nb=a+da,b+db
                            if 0<=na<H and 0<=nb<W and not seen[na][nb] and inp[na][nb]!=bg:
                                stack.append((na,nb))
                rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
                rr0=min(rs); cc0=min(cs)
                hgt=max(rs)-rr0+1; wid=max(cs)-cc0+1
                if len(comp)>=4 and len(set(inp[p[0]][p[1]] for p in comp))>=3:
                    seed=(rr0,cc0,hgt,wid)
    out=[row[:] for row in inp]
    mr,mc=seed[0]+seed[2]//2,seed[1]+seed[3]//2
    markers=[(r,c) for r in range(H) for c in range(W) if inp[r][c]!=bg and not(seed[0]<=r<seed[0]+seed[2] and seed[1]<=c<seed[1]+seed[3])]
    blk=[[inp[seed[0]+i][seed[1]+j] for j in range(seed[3])] for i in range(seed[2])]
    for r,c in markers:
        dr,dc=r-mr,c-mc
        for i in range(seed[2]):
            for j in range(seed[3]):
                rr=i+dr; cc=j+dc
                if 0<=rr<H and 0<=cc<W:
                    out[rr][cc]=blk[i][j]
